def flatten_list(nested_list):
    """
    Flattens a given nested list structure into a single list.

    Args:
        nested_list (list): The nested list to flatten.

    Returns:
        list: A flattened version of the input list.
    """
    def _flatten(sublist):
        for element in sublist:
            if isinstance(element, list):
                yield from _flatten(element)  # Recursively flatten nested lists
            else:
                yield element  # Yield non-list elements as-is

    return list(_flatten(nested_list))
