def cal_sum(n):
    if n <= 0:
        return 0  # No terms to sum for invalid or zero input

    # Initial Perrin sequence values
    p0, p1, p2 = 3, 0, 2
    total_sum = p0 + p1 + p2  # Start with the sum of the first three terms

    if n == 1:
        return p0  # If n is 1, sum is just the first term
    elif n == 2:
        return p0 + p1  # If n is 2, sum is the first two terms
    elif n == 3:
        return total_sum  # If n is 3, sum is the first three terms

    for i in range(3, n):  # Start generating from the 4th term (index 3)
        next_p = p0 + p2  # P(n) = P(n-2) + P(n-3)
        total_sum += next_p
        p0, p1, p2 = p1, p2, next_p  # Update variables for the next term

    return total_sum
